mapper.select:
SELECT o.id, o.order_no AS orderNo, o.product_id AS productId, o.product_title AS productTitle, o.product_cover AS productCover, o.price, o.buyer_id AS buyerId, o.seller_id AS sellerId, o.contact, o.trade_location AS tradeLocation, o.remark, o.cancel_reason AS cancelReason, o.status, o.finish_time AS finishTime, o.create_time AS createTime, b.nickname AS buyerNickname, b.avatar AS buyerAvatar, s.nickname AS sellerNickname, s.avatar AS sellerAvatar FROM biz_order o LEFT JOIN sys_user b ON b.id = o.buyer_id LEFT JOIN sys_user s ON s.id = o.seller_id
o.deleted = 0
AND o.seller_id = #{userId}
AND o.buyer_id = #{userId}
AND o.status = #{query.status}
ORDER BY o.create_time DESC, o.id DESC
